create table public.workspace_notes(id uuid primary key default gen_random_uuid(),firm_id uuid not null references public.law_firms(id)on delete cascade,title text not null check(btrim(title)<>''),body text,urgency text not null default'normal'check(urgency in('normal','attention','urgent','critical')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.workspace_note_shares(id uuid primary key default gen_random_uuid(),firm_id uuid not null references public.law_firms(id)on delete cascade,note_id uuid not null references public.workspace_notes(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,permission text not null check(permission in('view','edit')),created_at timestamptz not null default now(),unique(note_id,user_id));
create table public.workspace_note_items(id uuid primary key default gen_random_uuid(),firm_id uuid not null references public.law_firms(id)on delete cascade,note_id uuid not null references public.workspace_notes(id)on delete cascade,content text not null check(btrim(content)<>''),completed boolean not null default false,position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.workspace_note_assets(id uuid primary key default gen_random_uuid(),firm_id uuid not null references public.law_firms(id)on delete cascade,note_id uuid not null references public.workspace_notes(id)on delete cascade,storage_path text not null unique,file_name text not null,mime_type text not null,file_size bigint not null check(file_size>=0 and file_size<=52428800),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index workspace_notes_firm_updated_idx on public.workspace_notes(firm_id,updated_at desc);create index workspace_note_shares_user_idx on public.workspace_note_shares(user_id,note_id);create index workspace_note_items_note_idx on public.workspace_note_items(note_id,position);create index workspace_note_assets_note_idx on public.workspace_note_assets(note_id,created_at);
alter table public.workspace_notes enable row level security;alter table public.workspace_note_shares enable row level security;alter table public.workspace_note_items enable row level security;alter table public.workspace_note_assets enable row level security;
create function private.can_view_workspace_note(target_note_id uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.workspace_notes n where n.id=target_note_id and(n.created_by=auth.uid()or private.has_firm_role(n.firm_id,array['owner'])or exists(select 1 from public.workspace_note_shares s where s.note_id=n.id and s.user_id=auth.uid())))$$;
create function private.can_edit_workspace_note(target_note_id uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.workspace_notes n where n.id=target_note_id and(n.created_by=auth.uid()or private.has_firm_role(n.firm_id,array['owner'])or exists(select 1 from public.workspace_note_shares s where s.note_id=n.id and s.user_id=auth.uid()and s.permission='edit')))$$;
create function private.can_manage_workspace_note(target_note_id uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.workspace_notes n where n.id=target_note_id and(n.created_by=auth.uid()or private.has_firm_role(n.firm_id,array['owner'])))$$;
revoke all on function private.can_view_workspace_note(uuid),private.can_edit_workspace_note(uuid),private.can_manage_workspace_note(uuid)from public,anon;grant execute on function private.can_view_workspace_note(uuid),private.can_edit_workspace_note(uuid),private.can_manage_workspace_note(uuid)to authenticated;
create policy workspace_notes_select on public.workspace_notes for select to authenticated using(private.can_view_workspace_note(id));
create policy workspace_notes_insert on public.workspace_notes for insert to authenticated with check(created_by=auth.uid()and private.has_firm_role(firm_id,array['owner','admin','manager','billing','professional','operator']));
create policy workspace_notes_update on public.workspace_notes for update to authenticated using(private.can_edit_workspace_note(id))with check(private.can_edit_workspace_note(id));
create policy workspace_notes_delete on public.workspace_notes for delete to authenticated using(private.can_manage_workspace_note(id));
create policy workspace_note_shares_select on public.workspace_note_shares for select to authenticated using(private.can_view_workspace_note(note_id));
create policy workspace_note_shares_write on public.workspace_note_shares for all to authenticated using(private.can_manage_workspace_note(note_id))with check(private.can_manage_workspace_note(note_id));
create policy workspace_note_items_select on public.workspace_note_items for select to authenticated using(private.can_view_workspace_note(note_id));
create policy workspace_note_items_write on public.workspace_note_items for all to authenticated using(private.can_edit_workspace_note(note_id))with check(private.can_edit_workspace_note(note_id));
create policy workspace_note_assets_select on public.workspace_note_assets for select to authenticated using(private.can_view_workspace_note(note_id));
create policy workspace_note_assets_write on public.workspace_note_assets for all to authenticated using(private.can_edit_workspace_note(note_id))with check(created_by=auth.uid()and private.can_edit_workspace_note(note_id));
grant select,insert,update,delete on public.workspace_notes,public.workspace_note_shares,public.workspace_note_items,public.workspace_note_assets to authenticated;
create function public.get_workspace_note_users()returns table(user_id uuid,display_name text)language sql stable security definer set search_path=''as $$select fm.user_id,coalesce(ulc.display_name,ulc.username)from public.firm_members me join public.firm_members fm on fm.firm_id=me.firm_id and fm.active join public.user_login_credentials ulc on ulc.user_id=fm.user_id where me.user_id=auth.uid()and me.active order by 2$$;revoke all on function public.get_workspace_note_users()from public,anon;grant execute on function public.get_workspace_note_users()to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('workspace-notes','workspace-notes',false,52428800,array['image/jpeg','image/png','image/webp','image/gif','audio/webm','audio/ogg','audio/mpeg','audio/mp4','audio/wav'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy workspace_notes_storage_select on storage.objects for select to authenticated using(bucket_id='workspace-notes'and private.can_view_workspace_note((storage.foldername(name))[2]::uuid));
create policy workspace_notes_storage_insert on storage.objects for insert to authenticated with check(bucket_id='workspace-notes'and private.can_edit_workspace_note((storage.foldername(name))[2]::uuid));
create policy workspace_notes_storage_delete on storage.objects for delete to authenticated using(bucket_id='workspace-notes'and private.can_edit_workspace_note((storage.foldername(name))[2]::uuid));
